---@type IDataInfo
local IDataInfo = Plugins.Require("data_info", isClient and "client.info.CDataInfo" or "server.info.SDataInfo")
---@class CustomLotteryInfo : IDataInfo
local CustomLotteryInfo = class("CustomLotteryInfo", IDataInfo)
---@type ItemContainerMgr
local ItemContainerMgr = T(Global, "ItemContainerMgr")
---@type ItemContainerUtil
local ItemContainerUtil = T(Global, "ItemContainerUtil")
---@type SCustomLotteryPkSender
local CustomLotteryPkSender = T(Global, "PidPacketSender")
---@type ItemInfoConfig
local ItemInfoConfig = T(Global, "ItemInfoConfig")
---@type table<number, number> 物品品质最低价值
local ItemMinWorth = {
    [1] = 10000,
    [2] = 10000,
    [3] = 10000,
    [4] = 10000,
}

function CustomLotteryInfo:onCreate()
    ---key, defValue, toSelf, toOther, saveDB
    self:initKey(Define.CustomLotteryInfoKey.IsOpen, false, true, true, true)
    self:initKey(Define.CustomLotteryInfoKey.Price, 10000, true, true, true)
    self:initKey(Define.CustomLotteryInfoKey.SetTimes, 1, true, true, true)
    self:initKey(Define.CustomLotteryInfoKey.LastTimes, 0, true, true, true)
    self:initKey(Define.CustomLotteryInfoKey.Records, {}, true, false, true)
    self:initKey(Define.CustomLotteryInfoKey.CloseTime, 0, true, true, true)
    self:initKey(Define.CustomLotteryInfoKey.StartTimes, 0, true, true, true)
    self:initKey(Define.CustomLotteryInfoKey.Players, {}, true, true, true)
end

---@param player SBasePlayer | CBasePlayer
function CustomLotteryInfo:setPlayer(player)
    self.player = player
    if isClient and player ~= PlayerManager:getClientPlayer() then
        return
    end
    self.container = ItemContainerMgr:createContainer(player.userId .. ":custom_lottery", 12)
    if isServer then
        ItemContainerMgr:registerSync(self.container.key, self.player)
    end
end

function CustomLotteryInfo:getMaxSetTimes()
    local maxTimes = 0
    for _, slot in pairs(self.container.slots) do
        if slot.itemId > 0 then
            maxTimes = maxTimes + 1
        end
    end
    return maxTimes
end

function CustomLotteryInfo:getMinPrice()
    local count = self.container:getContainerSize() - self.container:getEmptySlotCount()
    local price = 10000
    if count ~= 0 then
        local worth = 0
        for _, slot in pairs(self.container.slots) do
            if slot.itemId > 0 then
                local cfg = ItemInfoConfig:getCfg(slot.itemId, slot.meta)
                local quality = cfg and cfg.precious or 0
                worth = worth + (ItemMinWorth[quality] or 0)
            end
        end
        price = math.ceil(worth / count)
    end
    return math.min(math.max(price, 10000), 1000000000)
end

---@private
function CustomLotteryInfo:onContainerChange()
    if self.container:isEmpty() then
        self:setValue(Define.CustomLotteryInfoKey.IsOpen, false)
    end
    local maxTimes = self:getMaxSetTimes()
    local lastTimes = self:getValue(Define.CustomLotteryInfoKey.LastTimes)
    if lastTimes > maxTimes then
        self:setValue(Define.CustomLotteryInfoKey.LastTimes, maxTimes)
    end
    if self:isOpen() then
        return
    end
    local min = self:getMinPrice()
    local price = self:getValue(Define.CustomLotteryInfoKey.Price)
    if price < min then
        self:setValue(Define.CustomLotteryInfoKey.Price, min)
    end
end

---@private
function CustomLotteryInfo:onTick()
    if not self.container then
        return
    end
    if self:isOpen() then
        self.container:removeOperator(self.player.userId)
    else
        self.container:addOperator(self.player.userId)
        self:setValue(Define.CustomLotteryInfoKey.LastTimes, 0)
    end
end

function CustomLotteryInfo:isOpen()
    if self:getValue(Define.CustomLotteryInfoKey.IsOpen) then
        return os.time() < self:getValue(Define.CustomLotteryInfoKey.CloseTime)
    end
    return false
end

function CustomLotteryInfo:tryOpen()
    if self:isOpen() then
        return
    end
    if self:getMaxSetTimes() == 0 then
        return
    end
    if self:getValue(Define.CustomLotteryInfoKey.SetTimes) <= 0 then
        return
    end
    local maxTimes = math.min(self:getValue(Define.CustomLotteryInfoKey.SetTimes), self:getMaxSetTimes())
    self:setValue(Define.CustomLotteryInfoKey.LastTimes, maxTimes)
    self:setValue(Define.CustomLotteryInfoKey.StartTimes, maxTimes)
    self:setValue(Define.CustomLotteryInfoKey.CloseTime, os.time() + 300)
    self:setValue(Define.CustomLotteryInfoKey.IsOpen, true)
    self:setValue(Define.CustomLotteryInfoKey.Records, {})
end

function CustomLotteryInfo:trySetPrice(price)
    if self:isOpen() then
        return
    end
    if type(price) ~= "number" then
        return
    end
    local min = self:getMinPrice()
    if price < min or price > 1000000000 then
        return
    end
    self:setValue(Define.CustomLotteryInfoKey.Price, price)
end

function CustomLotteryInfo:trySetTimes(times)
    if self:isOpen() then
        return
    end
    if type(times) ~= "number" then
        return
    end
    if times < 1 or times > 12 then
        return
    end
    self:setValue(Define.CustomLotteryInfoKey.SetTimes, times)
end

---@param player SBasePlayer
function CustomLotteryInfo:tryLottery(player, params)
    if not self:isOpen() then
        return 1
    end
    local price = self:getValue(Define.CustomLotteryInfoKey.Price)
    if price ~= params.price then
        return 2
    end
    if ItemContainerUtil:container2str(self.container) ~= params.container then
        CustomLotteryPkSender:onSyncCustomLotteryData(player, self.player)
        return 2
    end
    if not self.player.info:inPrivateHome() then
        return 3
    end
    local weights = self:getMaxSetTimes()
    if weights == 0 or self:getValue(Define.CustomLotteryInfoKey.LastTimes) <= 0 then
        return 1
    end
    local inventory = player:getPlayerInventory()
    if not inventory.hotbar:getFirstEmptySlot() and not inventory.backpack:getFirstEmptySlot() then
        return 4
    end
    local random = HostApi.random("CustomLottery", 1, weights * 1000 + 1)
    local weight = 0
    ---@type ItemSlot
    local find
    for _, slot in pairs(self.container.slots) do
        if slot.itemId > 0 then
            weight = weight + 1000
            if weight >= random then
                find = slot
                break
            end
        end
    end
    if not find then
        return 1
    end
    PayHelper.payMoneySync(player, self.player.userId, CurrencyId.Currency, price, function()
        if player ~= self.player then
            CustomLotteryPkSender:sendCustomLotteryResultMsg(self.player, player.name, find)
        end
        local records = self:getValue(Define.CustomLotteryInfoKey.Records)
        local income
        if self.player.privilege:hasAdminPrivilege(Define.PrivilegeInfoKey.CustomLottery) then
            income = math.floor(price * 0.9)
        else
            income = math.floor(price * 0.8)
        end
        local record = (#records + 1) .. "," .. player.userId .. "," .. table.concat(find:encode(), ",") .. "," .. income
        table.insert(records, record)
        CustomLotteryPkSender:broadcastCustomLotteryNotice(player.name, self.player.name, find)
        CustomLotteryPkSender:onCustomLotteryResult(player, self.player.userId, find.index, find:encode())
        inventory:tryAddItem(find.itemId, find.meta, find.count)
        inventory:reportItemChange(find.itemId, find.meta, find.count, "CustomLottery", self.player.userId)
        self.player:addCurrency(income, "CustomLottery")
        self.player:getPlayerInventory():reportItemChange(find.itemId, find.meta, -find.count, "CustomLottery", player.userId)
        self:setValue(Define.CustomLotteryInfoKey.Records, records)
        self:decValue(Define.CustomLotteryInfoKey.LastTimes, 1)
        find:updateItem(0, 0, 0)
        if player ~= self.player then
            Plugins.CallTargetPluginFunc("data_info", "onSavePlayerDBData", player, true)
            Plugins.CallTargetPluginFunc("data_info", "onSavePlayerDBData", self.player, true)
            Plugins.CallTargetPluginFunc("item_container", "onSavePlayerDBData", player, true)
            Plugins.CallTargetPluginFunc("item_container", "onSavePlayerDBData", self.player, true)
        end
    end, nil, nil, "CustomLottery")
    return 0
end

function CustomLotteryInfo:onPlayerReady()
    if not self.container then
        return
    end
    if isServer then
        self:onContainerChange()
        self.container:addObserver(function()
            self:onContainerChange()
        end)
        self:addKeyObserver(Define.CustomLotteryInfoKey.LastTimes, function(_, _, value)
            if value <= 0 then
                self:setValue(Define.CustomLotteryInfoKey.IsOpen, false)
                self:setValue(Define.CustomLotteryInfoKey.Players, {})
            end
        end)
        if self:getValue(Define.CustomLotteryInfoKey.LastTimes) <= 0 then
            self:setValue(Define.CustomLotteryInfoKey.IsOpen, false)
        end
        if not self:isOpen() then
            self:setValue(Define.CustomLotteryInfoKey.Players, {})
        end
    end
end

return CustomLotteryInfo